t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
w=2*np.pi/15; s=np.sin(w*t); c=np.cos(w*t)
L=np.log(P)
lib={}
Pf={'1':np.ones_like(P),'P':P,'P2':P**2,'P3':P**3,'lP':L,'PlP':P*L,'P2lP':P**2*L,'lP2':L**2,'1/P':1/P,'sqrtP':np.sqrt(P)}
tf={'1':np.ones_like(t),'t':t,'t2':t**2,'t3':t**3}
tr={'1':np.ones_like(t),'s':s,'c':c,'s2':s*s,'sc':s*c,'c2':c*c}
for a,pv in Pf.items():
    for b,tv in tf.items():
        for d,trv in tr.items():
            lib[f'{a}*{b}*{d}']=pv*tv*trv
keys=list(lib.keys())
sel=[]
for step in range(12):
    bestk=None
    for k in keys:
        if k in sel: continue
        A=np.column_stack([lib[q] for q in sel+[k]])
        co=np.linalg.lstsq(A,y,rcond=None)[0]
        nm=np.mean((y-A@co)**2)/np.var(y)
        if bestk is None or nm<bestk[0]: bestk=(nm,k)
    sel.append(bestk[1]); print(step,bestk[1],bestk[0])
